import React from 'react';

function Navbar({ user, onLogout, onNav }) {
  return (
    <nav className="w-full bg-gradient-button py-4 flex justify-center items-center shadow-lg">
      <button 
        className="text-white font-semibold mx-4 text-lg hover:text-yellow-300 transition-colors duration-200 bg-transparent border-none cursor-pointer"
        onClick={() => onNav('books')}
      >
        Books
      </button>
      {user?.role === 'librarian' && (
        <button 
          className="text-white font-semibold mx-4 text-lg hover:text-yellow-300 transition-colors duration-200 bg-transparent border-none cursor-pointer"
          onClick={() => onNav('requests')}
        >
          Requests
        </button>
      )}
      <div className="flex-1"></div>
      {user ? (
        <button 
          className="text-white font-semibold cursor-pointer ml-6 text-lg underline bg-transparent border-none hover:text-yellow-300 transition-colors duration-200"
          onClick={onLogout}
        >
          Logout
        </button>
      ) : null}
    </nav>
  );
}

export default Navbar;
